import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { notificationApi } from '../../api/services';
import { Button, Badge } from '../../components/ui';
import { format } from 'date-fns';
import { CheckCheck } from 'lucide-react';
import toast from 'react-hot-toast';

const typeColor = { DOCUMENT_EXPIRY: 'red', PROBATION: 'yellow', TRANSFER: 'blue', PROMOTION: 'green', GENERAL: 'gray' };

export default function NotificationsPage() {
  const qc = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ['notifications'],
    queryFn: () => notificationApi.getAll({ page: 0, size: 50 }),
  });

  const markAllMutation = useMutation({
    mutationFn: notificationApi.markAllRead,
    onSuccess: () => { qc.invalidateQueries(['notifications']); qc.invalidateQueries(['unread-count']); toast.success('All marked as read'); },
  });

  const markOneMutation = useMutation({
    mutationFn: notificationApi.markRead,
    onSuccess: () => { qc.invalidateQueries(['notifications']); qc.invalidateQueries(['unread-count']); },
  });

  const notifications = data?.data?.data?.content || data?.data?.data || [];

  return (
    <div className="space-y-4 max-w-3xl">
      <div className="flex justify-end">
        <Button variant="secondary" onClick={() => markAllMutation.mutate()} disabled={markAllMutation.isPending}>
          <CheckCheck size={16} /> Mark All Read
        </Button>
      </div>

      {isLoading ? (
        <p className="text-slate-400 text-sm">Loading...</p>
      ) : notifications.length === 0 ? (
        <div className="bg-white rounded-xl border border-slate-200 p-10 text-center text-slate-400">
          No notifications
        </div>
      ) : (
        <div className="space-y-2">
          {notifications.map((n) => (
            <div
              key={n.id}
              onClick={() => !n.read && markOneMutation.mutate(n.id)}
              className={`bg-white rounded-xl border p-4 cursor-pointer transition-colors ${
                n.read ? 'border-slate-200 opacity-70' : 'border-indigo-200 bg-indigo-50/30'
              }`}
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <Badge label={n.type} color={typeColor[n.type] || 'gray'} />
                    {!n.read && <span className="w-2 h-2 bg-indigo-500 rounded-full" />}
                  </div>
                  <p className="text-sm font-medium text-slate-800">{n.title}</p>
                  <p className="text-sm text-slate-500 mt-0.5">{n.message}</p>
                </div>
                <p className="text-xs text-slate-400 whitespace-nowrap">
                  {n.createdAt ? format(new Date(n.createdAt), 'dd MMM, HH:mm') : ''}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
